import{copy,newTic,ticMove,ticAI,ticResult,newDots,dotsMove,dotsAI,newCheckers,checkersMoves,checkersMove,checkersAI,owner,newWord,customWord,wordMove}from'./rules.js';
const app=document.querySelector('#app'),shelfMarkup=app.innerHTML,KEY='table-for-two-v1';
const names={tic:'Tic-tac-toe',dots:'Dots & boxes',word:'Hangman',checkers:'Checkers'};
const help={tic:'Take turns placing a mark. Make a line of three across, down, or diagonally to win. Blue goes first. The game ends in a tie as soon as every possible line contains both marks, even if squares are still empty.',dots:'Tap between two dots to draw a line. The player drawing the fourth side wins that box, even if the other player drew its other sides. A claimed box shows its owner and stays theirs. Claim a box and take another turn. The player with the most boxes wins.',word:'Guess letters to find the word. Picture clues help new readers. You have eight missed guesses. Play together with a word picked by the computer, or make a secret word for each other.',checkers:'Blue moves first. Tap a piece, then a highlighted square. Regular pieces move and jump diagonally forward. You must take a jump when one is available and finish any extra jumps with that piece. Reach the far edge to become a king; your turn ends when crowned. Kings can move and jump both ways, one square or jump at a time. Win when the other player has no legal move. Repeating a position three times, or 80 moves without a capture or new king, is a tie.'};
let data={version:1,mode:'computer',level:'gentle',dotSize:3,wordGroup:'All',games:{}},storageOK=true,screen='home',selected=null,timer=null,wordSetup=false,offlineReady=false;
function validState(game,s){if(!s||typeof s!=='object')return false;if(game==='word')return /^[A-Z]{2,12}$/.test(s.word)&&Array.isArray(s.guesses);if(![1,2].includes(s.turn))return false;if(game==='tic')return Array.isArray(s.board)&&s.board.length===9;if(game==='checkers')return Array.isArray(s.board)&&s.board.length===64&&s.repeats&&typeof s.repeats==='object';return [2,3,4].includes(s.n)&&s.h?.length===s.n*(s.n+1)&&s.v?.length===s.n*(s.n+1)&&s.boxes?.length===s.n*s.n}
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved?.version===1&&saved.games&&typeof saved.games==='object'){data={...data,...saved};if(!['computer','together'].includes(data.mode))data.mode='computer';if(!['gentle','tricky'].includes(data.level))data.level='gentle';for(const game of Object.keys(data.games)){const item=data.games[game];if(!names[game]||!item?.state||!Array.isArray(item.history)||!validState(game,item.state))delete data.games[game]}}}catch{storageOK=false}
function save(){try{localStorage.setItem(KEY,JSON.stringify(data));storageOK=true}catch{storageOK=false}}
function esc(str){return String(str).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function state(){return data.games[screen]?.state}
function player(p){return p===1?(data.mode==='computer'?'You':'Blue'):(data.mode==='computer'?'Computer':'Coral')}
function stopComputer(){clearTimeout(timer);timer=null}
function newState(game,previous){if(game==='tic')return newTic();if(game==='dots')return newDots(data.dotSize);if(game==='checkers')return newCheckers();return newWord(data.wordGroup,previous?.word||'')}
function start(game){if(!names[game])return;stopComputer();screen=game;selected=null;wordSetup=false;if(!data.games[game])data.games[game]={state:newState(game),history:[]};save();render();window.scrollTo(0,0)}
function home(){stopComputer();speechSynthesisSafeCancel();screen='home';selected=null;wordSetup=false;render();window.scrollTo(0,0)}
function speechSynthesisSafeCancel(){if('speechSynthesis'in window)window.speechSynthesis.cancel()}
function reset(game=screen){stopComputer();const prior=data.games[game]?.state;data.games[game]={state:newState(game,prior),history:[]};selected=null;wordSetup=false;save();render()}
function remember(){const item=data.games[screen];item.history.push(copy(item.state));if(item.history.length>64)item.history.shift()}
function undo(){const item=data.games[screen];if(!item?.history.length)return;stopComputer();item.state=item.history.pop();selected=null;save();render()}
function commit(next){if(!next)return;data.games[screen].state=next;selected=null;save();render()}
function humanMove(kind,...args){const s=state();if(!s||s.result||wordSetup||kind!==screen||(screen!=='word'&&data.mode==='computer'&&s.turn===2))return false;const next=kind==='tic'?ticMove(s,...args):kind==='dots'?dotsMove(s,...args):kind==='checkers'?checkersMove(s,...args):wordMove(s,...args);if(!next)return false;remember();commit(next);return true}
function scheduleComputer(){stopComputer();const s=state();if(screen==='home'||screen==='word'||data.mode!=='computer'||s?.result||s?.turn!==2||document.hidden||document.querySelector('dialog[open]'))return;const game=screen;timer=setTimeout(()=>{timer=null;if(screen!==game)return;const current=state();if(current.result||current.turn!==2)return;let next;if(game==='tic'){const m=ticAI(current,data.level);next=ticMove(current,m)}else if(game==='dots'){const m=dotsAI(current,data.level);next=m&&dotsMove(current,m.axis,m.index)}else{const m=checkersAI(current,data.level);next=m&&checkersMove(current,m.from,m.to)}commit(next)},650)}
function header(){return`<header class="masthead"><button class="brand brand-button" data-action="home" aria-label="Table for Two, all games"><span class="brand-icon" aria-hidden="true">t²</span> table for two<span class="brand-dot">.</span></button><button class="text-button" data-action="install">Add to your phone</button></header>`}
function offlineText(){return offlineReady?'✓ Ready for offline play':navigator.onLine?'4 games · Zero ads':'Offline · Your turn, anywhere'}
function renderHome(){app.innerHTML=shelfMarkup;app.querySelector('.masthead').outerHTML=header();app.querySelector('.intro').textContent='Pick a game. Pull up a chair.';app.querySelector('.shelf-heading').insertAdjacentHTML('beforeend',`<div class="home-modes"><div class="segmented" role="group" aria-label="Who is playing?"><button data-mode="together" aria-pressed="${data.mode==='together'}">Play together</button><button data-mode="computer" aria-pressed="${data.mode==='computer'}">Play computer</button></div><span class="mode-note">${data.mode==='computer'?'Team up against a gentle opponent.':'Two players. One screen.'}</span></div>`);app.querySelectorAll('[data-game]').forEach(b=>{const game=b.dataset.game;if(data.games[game]?.state.moves&&!data.games[game].state.result){b.querySelector('small').textContent='Your game is saved';b.insertAdjacentHTML('afterbegin','<span class="resume-badge">Resume</span>')}});app.querySelector('.shelf-footer').innerHTML=`<span id="offline-status">${offlineText()}</span><button class="text-button" data-action="install">Keep it on your Home Screen</button>`;if(!storageOK)app.querySelector('.shelf-footer').insertAdjacentHTML('beforebegin','<p class="storage-warning">Your browser cannot save right now. Keep this page open to keep your game.</p>')}
function statusText(s){if(s.result){if(screen==='word')return s.result.winner===1?'You found it!':'A good try! The word is '+s.word+'.';if(s.result.winner==='draw')return screen==='tic'&&s.result.reason==='blocked'?'A tie — no winning lines left.':'A tie! Another round?';return player(s.result.winner)+(data.mode==='computer'&&s.result.winner===1?' win!':' wins!')}if(screen==='word')return'Find the word together';if(s.turn===2&&data.mode==='computer')return'Computer is thinking…';if(screen==='checkers'&&s.forced!==null)return'One more jump with this piece';if(screen==='dots'&&s.lastScored)return player(s.turn)+(data.mode==='computer'&&s.turn===1?' get':' gets')+' another turn';return player(s.turn)+(data.mode==='computer'&&s.turn===1?'r turn':"’s turn")}
function renderGame(){const s=state();if(screen==='tic'&&!s.result){s.result=ticResult(s.board);if(s.result)save()}const item=data.games[screen],isWord=screen==='word';app.innerHTML=header()+`<main class="game-page"><nav class="game-nav"><button class="back" data-action="home">‹ All games</button><button class="text-button" data-action="rules">How to play</button></nav><div class="title-row"><h1 class="game-title">${names[screen]}</h1><span class="game-kicker">${isWord?'A WORD TO FIND':data.mode==='computer'?'YOU + COMPUTER':'YOU + ME'}</span></div>${isWord?wordControls():`<div class="game-settings"><div class="segmented" role="group" aria-label="Who is playing?"><button data-mode="together" aria-pressed="${data.mode==='together'}">Together</button><button data-mode="computer" aria-pressed="${data.mode==='computer'}">Computer</button></div>${data.mode==='computer'?`<label class="select-label"><span>Level</span><select id="difficulty"><option value="gentle" ${data.level==='gentle'?'selected':''}>Gentle</option><option value="tricky" ${data.level==='tricky'?'selected':''}>Tricky</option></select></label>`:''}${screen==='dots'?`<label class="select-label"><span>Board</span><select id="dot-size">${[2,3,4].map(n=>`<option value="${n}" ${s.n===n?'selected':''}>${n} × ${n}</option>`).join('')}</select></label>`:''}</div>`}${wordSetup?secretForm():`<div class="turn-banner ${s.result?'finished':''} ${!isWord&&s.turn===2?'coral-turn':''}" role="status" aria-live="polite"><span class="turn-symbol" aria-hidden="true">${isWord?'✦':s.result?'★':s.turn===1?'●':'○'}</span><span>${statusText(s)}</span></div>${screen==='tic'?ticBoard(s):screen==='dots'?dotsBoard(s):screen==='checkers'?checkersBoard(s):wordBoard(s)}<div class="game-actions"><button class="secondary" data-action="undo" ${!item.history.length?'disabled':''}>Undo</button><button class="primary" data-action="reset">${s.result?(isWord?'Next word':'Play again'):'New '+(isWord?'word':'game')}</button></div><p class="game-footnote">${isWord?'A little help is always welcome.':screen==='tic'?'Three in a row. Across, down, or diagonal.':screen==='dots'?'Close a box, then take another turn.':'Tap a piece, then a glowing square.'}</p>`}${!storageOK?'<p class="storage-warning">Saving is unavailable. Keep this page open to keep your game.</p>':''}</main>`;scheduleComputer()}
function ticBoard(s){const locked=s.result||(data.mode==='computer'&&s.turn===2);return`<div class="board tic-board" role="group" aria-label="Tic-tac-toe board">${s.board.map((v,i)=>`<button class="tic-cell ${v===2?'coral':''} ${s.result?.line.includes(i)?'winning':''}" data-cell="${i}" aria-label="Row ${Math.floor(i/3)+1}, column ${i%3+1}: ${v?(v===1?'blue cross':'coral circle'):'empty'}" ${v||locked?'disabled':''}>${v===1?'×':v===2?'○':''}</button>`).join('')}</div><div class="players"><span><i class="blue-chip"></i>${player(1)} · ×</span><span><i class="coral-chip"></i>${player(2)} · ○</span></div>`}
function dotsBoard(s){const locked=s.result||(data.mode==='computer'&&s.turn===2),n=s.n;let cells='';for(let r=0;r<=2*n;r++)for(let c=0;c<=2*n;c++){if(r%2===0&&c%2===0)cells+='<span class="dot" aria-hidden="true"></span>';else if(r%2===0){const i=r/2*n+(c-1)/2;cells+=edge('h',i,s.h[i],r/2,(c-1)/2,locked)}else if(c%2===0){const i=(r-1)/2*(n+1)+c/2;cells+=edge('v',i,s.v[i],(r-1)/2,c/2,locked)}else{const p=s.boxes[(r-1)/2*n+(c-1)/2];cells+=`<span data-owner="${p}" class="box ${p?'claimed p'+p:''}" aria-label="Box row ${(r+1)/2}, column ${(c+1)/2}${p?', '+player(p):', unclaimed'}">${p?`<span class="box-mark" aria-hidden="true">${p===1?'×':'○'}</span><span class="box-owner">${p===2&&data.mode==='computer'?'CPU':player(p)}</span>`:''}</span>`}}const a=s.boxes.filter(x=>x===1).length,b=s.boxes.filter(x=>x===2).length;return`<div class="score-row"><span class="score-blue"><span class="score-symbol p1" aria-hidden="true">×</span>${player(1)} <b>${a}</b></span><span class="score-coral"><span class="score-symbol p2" aria-hidden="true">○</span>${player(2)} <b>${b}</b></span></div><div class="board dots-board" style="--n:${n}" role="group" aria-label="Dots and boxes board">${cells}</div>`}
function edge(axis,index,p,r,c,locked){return`<button class="edge ${axis} ${p?'drawn p'+p:''}" data-edge="${axis}:${index}" aria-label="${axis==='h'?'Horizontal':'Vertical'} line, row ${r+1}, column ${c+1}${p?', '+player(p):''}" ${p||locked?'disabled':''}><span></span></button>`}
function checkersBoard(s){const legal=checkersMoves(s);if(s.forced!==null)selected=s.forced;const locked=s.result||(data.mode==='computer'&&s.turn===2),froms=new Set(legal.map(m=>m.from)),targets=new Set(legal.filter(m=>m.from===selected).map(m=>m.to));let board='';for(let i=0;i<64;i++){const p=s.board[i],dark=(Math.floor(i/8)+i%8)%2===1,canPick=!locked&&(p&&froms.has(i)||targets.has(i));board+=`<button class="checker-cell ${dark?'dark':'light'} ${selected===i?'selected':''} ${targets.has(i)&&!locked?'target':''}" data-square="${i}" aria-label="${String.fromCharCode(65+i%8)}${8-Math.floor(i/8)}: ${p?(owner(p)===1?'blue':'coral')+(p<0?' king':' piece'):'empty'}${targets.has(i)?', legal destination':''}" ${!canPick?'disabled':''}>${p?`<span class="piece p${owner(p)} ${froms.has(i)&&!locked?'movable':''}">${p<0?'♛':''}</span>`:''}</button>`}return`<div class="checkers-hint">${!s.result&&legal.length&&legal[0].capture!==null?'A jump is available — jumps must be taken.':'Reach the other side to make a king.'}</div><div class="board checkers-board" role="group" aria-label="Checkers board">${board}</div><div class="players"><span><i class="blue-chip"></i>${player(1)} · ${s.board.filter(p=>owner(p)===1).length} pieces</span><span><i class="coral-chip"></i>${player(2)} · ${s.board.filter(p=>owner(p)===2).length} pieces</span></div>`}
function wordControls(){return`<div class="game-settings word-settings"><button class="secondary small" data-action="secret">Make a secret word</button><label class="select-label"><span>Words</span><select id="word-group">${['All','Animals','Our world','Food'].map(g=>`<option ${data.wordGroup===g?'selected':''}>${g}</option>`).join('')}</select></label></div>`}
function secretForm(){return`<section class="secret-panel"><div class="secret-mark" aria-hidden="true">Aa</div><h2>A word just for you</h2><p>One player looks away while the other types a word.</p><form id="secret-form"><label for="secret-word">Your secret word</label><input id="secret-word" type="password" autocomplete="off" autocapitalize="characters" spellcheck="false" minlength="2" maxlength="12" pattern="[A-Za-z]{2,12}" required aria-describedby="secret-tip" inputmode="text"><p id="secret-tip">2–12 letters. No spaces or numbers.</p><p id="secret-error" role="alert"></p><button class="primary" type="submit">Hide & pass the phone</button><button class="text-button" type="button" data-action="cancel-secret">Cancel</button></form></section>`}
function wordBoard(s){const misses=s.guesses.filter(c=>!s.word.includes(c)).length;return`<section class="word-clue"><span class="picture-clue" role="img" aria-label="Picture clue">${s.picture}</span><div><p class="eyebrow">${esc(s.group)}</p><p class="clue-text">${esc(s.clue)}</p>${'speechSynthesis'in window?'<button class="text-button listen" data-action="listen">♪ Hear the clue</button>':''}</div></section><div class="word-slots" style="--letters:${s.word.length}" role="group" aria-label="${s.word.length} letter word">${[...s.word].map((c,i)=>`<span class="letter-tile ${s.guesses.includes(c)?'found':s.result?'revealed':''}" aria-label="Letter ${i+1}: ${s.guesses.includes(c)||s.result?c:'unknown'}">${s.guesses.includes(c)||s.result?c:'<span aria-hidden="true">_</span>'}</span>`).join('')}</div><div class="chances"><div class="chance-dots" aria-label="${8-misses} guesses left">${Array.from({length:8},(_,i)=>`<span class="${i<8-misses?'remaining':''}" aria-hidden="true"></span>`).join('')}</div><span>${8-misses} misses left</span></div><div class="keyboard" role="group" aria-label="Guess a letter">${['QWERTYUIOP','ASDFGHJKL','ZXCVBNM'].map(row=>`<div class="key-row">${[...row].map(c=>`<button class="key ${s.guesses.includes(c)?s.word.includes(c)?'correct':'missed':''}" data-letter="${c}" aria-label="${c}${s.guesses.includes(c)?s.word.includes(c)?', found':', missed':''}" ${s.guesses.includes(c)||s.result?'disabled':''}>${c}</button>`).join('')}</div>`).join('')}</div>`}
function render(){if(screen==='home')renderHome();else renderGame()}
function modal(title,content,confirmLabel,callback){stopComputer();document.querySelector('dialog')?.remove();const dialog=document.createElement('dialog');dialog.className='modal';dialog.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="close-button" aria-label="Close">×</button></div><div class="dialog-content">${content}</div><div class="dialog-actions"><button class="${confirmLabel?'secondary':'primary'}" data-dismiss>${confirmLabel?'Keep playing':'Got it'}</button>${confirmLabel?`<button class="primary" data-confirm>${confirmLabel}</button>`:''}</div>`;document.body.append(dialog);dialog.querySelector('.close-button').onclick=()=>dialog.close();dialog.querySelector('[data-dismiss]').onclick=()=>dialog.close();dialog.querySelector('[data-confirm]')?.addEventListener('click',()=>{dialog.close();callback()});dialog.addEventListener('close',()=>{dialog.remove();scheduleComputer()});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.showModal()}
function confirmReset(callback,label='Start fresh'){const s=state();if(s?.moves&&!s.result)modal('Start a fresh game?','<p>This will replace the game on this board.</p>',label,callback);else callback()}
function changeMode(mode){if(mode===data.mode)return;const unfinished=Object.entries(data.games).filter(([game,item])=>game!=='word'&&item.state.moves&&!item.state.result);const apply=()=>{stopComputer();data.mode=mode;for(const game of ['tic','dots','checkers'])delete data.games[game];if(screen!=='home'&&screen!=='word')data.games[screen]={state:newState(screen),history:[]};selected=null;save();render()};if(unfinished.length)modal('Switch players?','<p>Switching players starts fresh boards for tic-tac-toe, dots & boxes, and checkers.</p>','Switch players',apply);else apply()}
const actions={home,undo,reset:()=>confirmReset(()=>reset()),rules:()=>modal('How to play',`<p>${help[screen]}</p>${screen==='word'?'<p>We use eight dots for your chances instead of drawing a hanging figure.</p>':data.mode==='computer'?'<p><strong>Gentle:</strong> a relaxed opponent for learning. <strong>Tricky:</strong> thinks further ahead.</p>':''}`),install:()=>modal('A little game shelf, always handy',`<ol><li>Open this website in <strong>Safari</strong> on your iPhone or iPad.</li><li>Tap <strong>Share</strong>, then <strong>Add to Home Screen</strong>.</li><li>If shown, turn on <strong>Open as Web App</strong>, then tap <strong>Add</strong>.</li><li>Open the new icon while online once. Look for <strong>Ready for offline play</strong> on the game shelf.</li></ol><p>Try opening it in airplane mode before your next meal out. Games save on this device; clearing website data removes saved games.</p>`),secret:()=>{stopComputer();wordSetup=true;render();document.querySelector('#secret-word')?.focus()},'cancel-secret':()=>{wordSetup=false;render()},listen:()=>{const s=state();if(!s||!('speechSynthesis'in window))return;speechSynthesisSafeCancel();const utterance=new SpeechSynthesisUtterance(s.clue);utterance.lang='en-US';utterance.rate=.8;window.speechSynthesis.speak(utterance)}};
app.addEventListener('click',event=>{const b=event.target.closest('button');if(!b||b.disabled)return;if(b.dataset.game)start(b.dataset.game);else if(b.dataset.action)actions[b.dataset.action]?.();else if(b.dataset.mode)changeMode(b.dataset.mode);else if(b.dataset.cell!==undefined)humanMove('tic',Number(b.dataset.cell));else if(b.dataset.edge){const[axis,i]=b.dataset.edge.split(':');humanMove('dots',axis,Number(i))}else if(b.dataset.letter)humanMove('word',b.dataset.letter);else if(b.dataset.square!==undefined){const i=Number(b.dataset.square),s=state(),legal=checkersMoves(s);if(selected!==null&&legal.some(m=>m.from===selected&&m.to===i))humanMove('checkers',selected,i);else if(legal.some(m=>m.from===i)){selected=i;render()}}});
app.addEventListener('change',event=>{const el=event.target;if(el.id==='difficulty'){data.level=el.value;save();render()}else if(el.id==='dot-size'){const next=Number(el.value);el.value=String(state().n);confirmReset(()=>{data.dotSize=next;reset()})}else if(el.id==='word-group'){const next=el.value;el.value=data.wordGroup;confirmReset(()=>{data.wordGroup=next;reset()})}});
app.addEventListener('submit',event=>{if(event.target.id!=='secret-form')return;event.preventDefault();const input=document.querySelector('#secret-word'),next=customWord(input.value);if(!next){document.querySelector('#secret-error').textContent='Use 2–12 letters, with no spaces.';return}input.value='';data.games.word={state:next,history:[]};wordSetup=false;save();render()});
document.addEventListener('keydown',event=>{if(screen==='word'&&!wordSetup&&!document.querySelector('dialog[open]')&&!['INPUT','SELECT','TEXTAREA'].includes(event.target.tagName)&&!event.ctrlKey&&!event.metaKey&&/^[a-z]$/i.test(event.key))humanMove('word',event.key.toUpperCase())});
document.addEventListener('visibilitychange',()=>{if(document.hidden){save();stopComputer();speechSynthesisSafeCancel()}else scheduleComputer()});window.addEventListener('pagehide',save);
function updateOfflineLabel(){const el=document.querySelector('#offline-status');if(el)el.textContent=offlineText()}
window.addEventListener('online',updateOfflineLabel);window.addEventListener('offline',updateOfflineLabel);render();
if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js').then(async registration=>{await navigator.serviceWorker.ready;const worker=registration.active;if(worker){const channel=new MessageChannel();channel.port1.onmessage=e=>{if(e.data==='CACHE_READY'){offlineReady=true;updateOfflineLabel()}};worker.postMessage('CACHE_STATUS',[channel.port2])}}).catch(()=>{})}
const context=document.modelContext;
if(context?.registerTool){const lifecycle=new AbortController();const tools=[{name:'read_game_state',description:'Read the current game and legal moves. Secret words stay hidden until solved.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){const s=state();if(!s)return{screen:'home',games:Object.keys(names),mode:data.mode};if(screen==='word')return{game:screen,letters:[...s.word].map(c=>s.guesses.includes(c)||s.result?c:'_'),guesses:s.guesses,result:s.result};return{game:screen,mode:data.mode,state:copy(s),...(screen==='checkers'?{legalMoves:checkersMoves(s)}:{})}}},{name:'open_game',description:'Open a game, resuming its saved board or starting an empty board.',inputSchema:{type:'object',properties:{game:{type:'string',enum:Object.keys(names)}},required:['game'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!names[input?.game]||Object.keys(input).some(k=>k!=='game'))throw Error('Choose a supported game');start(input.game);return{game:screen,status:'opened'}}}];for(const tool of tools){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
